#!/usr/bin/env python3
"""Inline an SVG's <style> class rules as presentation attributes.

GitHub sanitises <style> out of SVGs rendered through <img>, so any element styled only by
a CSS class loses its font, size and colour. Converting the rules to attributes on each
element keeps the diagram looking the same on GitHub as it does locally.
"""

import re
import sys
from pathlib import Path

# CSS properties that have a direct SVG presentation-attribute equivalent.
ATTRIBUTE_PROPERTIES = {
    "font-family", "font-size", "font-weight", "font-style",
    "fill", "fill-opacity", "stroke", "stroke-width", "stroke-opacity",
    "letter-spacing", "word-spacing", "text-anchor", "opacity", "text-transform",
}


def parse_style_block(svg_text):
    """{class name: {property: value}} from every <style> block."""
    rules = {}
    for block in re.findall(r"<style[^>]*>(.*?)</style>", svg_text, re.S):
        for selectors, body in re.findall(r"([^{}]+)\{([^{}]*)\}", block):
            declarations = {}
            for declaration in body.split(";"):
                if ":" not in declaration:
                    continue
                prop, _, value = declaration.partition(":")
                prop, value = prop.strip(), value.strip()
                if prop in ATTRIBUTE_PROPERTIES and value:
                    declarations[prop] = value
            if not declarations:
                continue
            for selector in selectors.split(","):
                selector = selector.strip()
                if selector.startswith(".") and " " not in selector:
                    rules.setdefault(selector[1:], {}).update(declarations)
    return rules


def inline_rules(svg_text, rules):
    """Add each class's declarations to its elements as attributes.

    Attributes already on the element win, so any deliberate per-element override survives.
    """
    def replace(match):
        tag, attrs = match.group(1), match.group(2)
        classes = re.search(r'class="([^"]*)"', attrs)
        if not classes:
            return match.group(0)

        declarations = {}
        for name in classes.group(1).split():
            declarations.update(rules.get(name, {}))
        if not declarations:
            return match.group(0)

        existing = set(re.findall(r'([a-zA-Z-]+)\s*=', attrs))
        additions = "".join(
            f' {prop}="{value}"'
            for prop, value in declarations.items()
            if prop not in existing
        )
        return f"<{tag}{attrs}{additions}>"

    return re.sub(r"<([a-zA-Z][\w-]*)((?:[^<>\"]|\"[^\"]*\")*?)>", replace, svg_text)


def main():
    if len(sys.argv) != 3:
        print("usage: inline_svg_css.py <input.svg> <output.svg>", file=sys.stderr)
        return 2

    source = Path(sys.argv[1])
    svg_text = source.read_text(encoding="utf-8")

    rules = parse_style_block(svg_text)
    if not rules:
        print("No class rules found; nothing to inline.", file=sys.stderr)
        return 1

    inlined = inline_rules(svg_text, rules)
    # Keep the <style> block: browsers opening the file directly still use it, and it is
    # harmless where it is stripped.
    Path(sys.argv[2]).write_text(inlined, encoding="utf-8")

    styled = len(re.findall(r'class="', svg_text))
    print(f"Inlined {len(rules)} class rules across {styled} elements -> {sys.argv[2]}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

